import{_ as l,C as r,o as n,c as h,j as e,a as t,E as o,a5 as c}from"./chunks/framework.CyyS6Zdm.js";const q=JSON.parse('{"title":"图片裁切","description":"","frontmatter":{},"headers":[],"relativePath":"components/image-cropper.md","filePath":"components/image-cropper.md","lastUpdated":1787235652000}'),p={name:"components/image-cropper.md"},s={id:"图片裁切",tabindex:"-1"};function g(m,d,u,b,x,f){const i=r("Badge"),a=r("XhDemo");return n(),h("div",null,[e("h1",s,[d[0]||(d[0]=t("图片裁切 ",-1)),o(i,{type:"info",text:"image-cropper"}),d[1]||(d[1]=t()),d[2]||(d[2]=e("a",{class:"header-anchor",href:"#图片裁切","aria-label":'Permalink to "图片裁切 <Badge type="info" text="image-cropper" />"'},"​",-1))]),d[3]||(d[3]=c('<p>在一张图上框出要保留的那一块。框可以整体拖动，八个把手各拉一条边或一个角，可锁定宽高比、可设最小尺寸，也能缩放与旋转来看清细节。裁切矩形以源图的自然像素记录，出图那一步由使用者自己决定什么时候做、做成什么。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>上传头像、封面、缩略图之前，让用户自己决定保留哪一块。</li><li>需要固定产出比例（16:9 的封面、1:1 的头像）的图片录入。</li><li>需要把裁切结果连同表单一起提交：给了 <code>name</code>，矩形会以 <code>x,y,width,height</code> 随表单发出去。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>只是把图片摆在页面上：用<a href="./image">图片</a>。</li><li>只要放大看清楚、翻页浏览，不改数据：用<a href="./image-viewer">图片查看器</a>。</li><li>只是选文件、还没到框选这一步：用<a href="./file-upload">文件上传</a>。</li><li>要调的是一个一维的量（亮度、缩放倍率本身）：用<a href="./slider">滑块</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>裁切矩形的单位是源图自然像素，与图片显示多大无关；换一块屏幕、换一个容器宽度，值不变。</li><li>缩放与旋转同时作用在图片和裁切框上，两者始终贴合；它们只改呈现，不改裁切矩形与源图像素的对应关系。</li><li>指针位移会按当前的缩放与旋转反算回图片坐标系，放大之后拖动依然跟手。</li><li>一次拖动的位移从按下那一刻的矩形整体算起，不逐帧累加，长距离拖动不会漂。</li><li>锁定宽高比时，拉角由位移更大的那条轴当驱动，另一条边跟着算；拉边则由那条边驱动。</li><li>受控与非受控两态齐全：<code>value</code> / <code>defaultValue</code> 管裁切矩形，<code>zoom</code> / <code>defaultZoom</code> 管缩放倍率。</li><li><code>onValueChangeEnd</code> 覆盖指针与键盘两条路：一次指针拖动松手时发一次，一次方向键微调也发一次（一按就是一次改完的操作）。矩形没真的变（在框上原地点一下、顶到图片边界推不动）不发。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>在图上框出要保留的那一块：整块可拖动，八个把手各拉一条边或一个角；裁切矩形以源图的自然像素记录</p>',10)),o(a,{src:"image-cropper/01-basic"}),d[4]||(d[4]=e("h3",{id:"锁定宽高比",tabindex:"-1"},[t("锁定宽高比 "),e("a",{class:"header-anchor",href:"#锁定宽高比","aria-label":'Permalink to "锁定宽高比"'},"​")],-1)),d[5]||(d[5]=e("p",null,"给了 aspectRatio，拉角由位移更大的那条轴驱动、另一条边跟着算，产出比例恒定",-1)),o(a,{src:"image-cropper/02-aspect-ratio"}),d[6]||(d[6]=e("h3",{id:"圆形裁切",tabindex:"-1"},[t("圆形裁切 "),e("a",{class:"header-anchor",href:"#圆形裁切","aria-label":'Permalink to "圆形裁切"'},"​")],-1)),d[7]||(d[7]=e("p",null,"shape 只改遮罩与描边的样子，裁切矩形还是那个矩形；配 1:1 比例即头像裁切",-1)),o(a,{src:"image-cropper/03-round"}),d[8]||(d[8]=e("h3",{id:"缩放与旋转",tabindex:"-1"},[t("缩放与旋转 "),e("a",{class:"header-anchor",href:"#缩放与旋转","aria-label":'Permalink to "缩放与旋转"'},"​")],-1)),d[9]||(d[9]=e("p",null,"两者同时作用在图片与裁切框上，看得更清楚；裁切矩形与源图像素的对应关系一点不变",-1)),o(a,{src:"image-cropper/04-zoom-rotate"}),d[10]||(d[10]=e("h3",{id:"受控",tabindex:"-1"},[t("受控 "),e("a",{class:"header-anchor",href:"#受控","aria-label":'Permalink to "受控"'},"​")],-1)),d[11]||(d[11]=e("p",null,"传了 value 就由宿主说了算：组件只发变更意图，写回去之后框才动",-1)),o(a,{src:"image-cropper/05-controlled"}),d[12]||(d[12]=e("h3",{id:"导出裁切结果",tabindex:"-1"},[t("导出裁切结果 "),e("a",{class:"header-anchor",href:"#导出裁切结果","aria-label":'Permalink to "导出裁切结果"'},"​")],-1)),d[13]||(d[13]=e("p",null,"出图不归组件管：拿 getCropRect() 的矩形喂给 cropToCanvas，画出来的是一张新画布",-1)),o(a,{src:"image-cropper/06-export"}),d[14]||(d[14]=e("h3",{id:"禁用与只读",tabindex:"-1"},[t("禁用与只读 "),e("a",{class:"header-anchor",href:"#禁用与只读","aria-label":'Permalink to "禁用与只读"'},"​")],-1)),d[15]||(d[15]=e("p",null,"禁用把裁切框与把手一起摘出 Tab 序列；只读仍可聚焦、仍念得出来，只是改不动",-1)),o(a,{src:"image-cropper/07-disabled"}),d[16]||(d[16]=c('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-image-cropper&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhImageCropperCropArea</code> <code>XhImageCropperCropHandle</code> <code>XhImageCropperGrid</code> <code>XhImageCropperHiddenInput</code> <code>XhImageCropperImage</code> <code>XhImageCropperRoot</code> <code>XhImageCropperViewport</code></td></tr><tr><td>组合式函数</td><td><code>useImageCropper</code></td></tr><tr><td>状态机</td><td><code>imageCropperMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/image-cropper.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;image-cropper&quot;</code>：<strong><code>root</code></strong> · <strong><code>viewport</code></strong> · <strong><code>image</code></strong> · <strong><code>crop-area</code></strong> · <code>crop-handle</code> · <code>grid</code> · <code>hidden-input</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>src</code></td><td><code>string</code></td><td></td><td>图片地址，原样写到 image 部件的 src 上。</td></tr><tr><td><code>alt</code></td><td><code>string</code></td><td></td><td>被裁切那张图的替代文本，原样写到 image 部件的 alt 上。 不给时 image 部件落 <code>alt=&quot;&quot;</code>：读屏就此跳过这张图，不去念地址。</td></tr><tr><td><code>aspectRatio</code></td><td><code>number | null</code></td><td></td><td>宽高比（宽 ÷ 高）。给了它，改尺寸时另一条边跟着算；null 与不给都表示不锁比例。 非有限数与非正数按不锁处理。</td></tr><tr><td><code>value</code></td><td><code>ImageCropperRect</code></td><td></td><td>裁切矩形。给定即受控：内部不再自改，只发 onValueChange。</td></tr><tr><td><code>defaultValue</code></td><td><code>ImageCropperRect</code></td><td></td><td></td></tr><tr><td><code>minWidth</code></td><td><code>number</code></td><td></td><td>裁切框的最小宽度，自然像素，默认 0。</td></tr><tr><td><code>minHeight</code></td><td><code>number</code></td><td></td><td>裁切框的最小高度，自然像素，默认 0。</td></tr><tr><td><code>zoom</code></td><td><code>number</code></td><td></td><td>显示缩放倍率，默认 1。给定即受控：setZoom 只发 onZoomChange。</td></tr><tr><td><code>defaultZoom</code></td><td><code>number</code></td><td></td><td></td></tr><tr><td><code>rotation</code></td><td><code>number</code></td><td></td><td>显示旋转角度，单位度，默认 0。 缩放与旋转只改图片与裁切框的呈现，裁切矩形与源图像素的对应关系不变。</td></tr><tr><td><code>shape</code></td><td><code>ImageCropperShape</code></td><td></td><td>裁切框外形，默认 rect。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>禁用：裁切框与把手退出 Tab 序列，指针与键盘都改不动，也不参与表单提交。</td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td><td>只读：仍可聚焦与被读屏念出，改不动。</td></tr><tr><td><code>name</code></td><td><code>string</code></td><td></td><td>表单字段名；给了才参与提交，值序列化成 <code>x,y,width,height</code>。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;ImageCropperTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onValueChange</code></td><td><code>(details: ImageCropperValueChangeDetails) =&gt; void</code></td><td></td><td>每次裁切矩形变化都发；拖动过程中会连续发很多次。</td></tr><tr><td><code>onValueChangeEnd</code></td><td><code>(details: ImageCropperValueChangeEndDetails) =&gt; void</code></td><td></td><td>只在一次拖动结束时发一次，适合拿来做裁切导出。</td></tr><tr><td><code>onZoomChange</code></td><td><code>(details: ImageCropperZoomChangeDetails) =&gt; void</code></td><td></td><td>缩放变化意图；受控时是唯一出口。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>value-change</code></td><td><code>ImageCropperValueChangeDetails</code></td><td>裁切矩形变化（拖动途中会连发）；detail 为 <code>{ value: { x, y, width, height } }</code></td></tr><tr><td><code>value-change-end</code></td><td><code>ImageCropperValueChangeEndDetails</code></td><td>一次指针拖动松手发一次，一次方向键微调也发一次；detail 为 <code>{ value: { x, y, width, height } }</code></td></tr><tr><td><code>zoom-change</code></td><td><code>ImageCropperZoomChangeDetails</code></td><td>缩放倍率变化；detail 为 <code>{ zoom: number }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhImageCropperRoot</code></td><td><code>default</code></td><td><code>ImageCropperRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>dragging</code> · <code>idle</code> · <code>resizing</code></p><p><strong>事件</strong>：<code>VALUE.SET</code> · <code>ZOOM.SET</code> · <code>IMAGE.LOAD</code> · <code>CROP.NUDGE</code> · <code>HANDLE.NUDGE</code> · <code>DRAG.START</code> · <code>RESIZE.START</code> · <code>DRAG.MOVE</code> · <code>DRAG.END</code> · <code>FORM.RESET</code></p><p><strong>判据</strong>：<code>canEdit</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useImageCropper</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>ImageCropperRect</code></td><td>当前裁切矩形，自然像素。</td></tr><tr><td><code>zoom</code></td><td><code>number</code></td><td></td></tr><tr><td><code>rotation</code></td><td><code>number</code></td><td></td></tr><tr><td><code>natural</code></td><td><code>ImageCropperSize</code></td><td>图片自然尺寸；未加载完成时是 0×0，此时裁切框还量不出位置。</td></tr><tr><td><code>dragging</code></td><td><code>boolean</code></td><td>正在整体拖动裁切框。</td></tr><tr><td><code>resizing</code></td><td><code>boolean</code></td><td>正在拉某个把手。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>getCropRect</code></td><td><code>() =&gt; ImageCropperRect</code></td><td>取一份当前裁切矩形的副本，交给 cropToCanvas 出图。</td></tr><tr><td><code>setValue</code></td><td><code>(next: ImageCropperRect) =&gt; void</code></td><td></td></tr><tr><td><code>setZoom</code></td><td><code>(next: number) =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getViewportProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getImageProps</code></td><td><code>() =&gt; T[&#39;img&#39;]</code></td><td></td></tr><tr><td><code>getCropAreaProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getCropHandleProps</code></td><td><code>(props: ImageCropperHandleProps) =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getGridProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>裁切框里的构图参考线，纯装饰。</td></tr><tr><td><code>getHiddenInputProps</code></td><td><code>() =&gt; T[&#39;input&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/slider/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>ArrowLeft</code> / <code>ArrowRight</code> / <code>ArrowUp</code> / <code>ArrowDown</code></td><td>focus on crop-area, 未禁用且非只读</td><td>裁切框整体平移一个自然像素，尺寸不变；走到图片边界就停住</td></tr><tr><td><code>Shift+ArrowLeft</code> / <code>Shift+ArrowRight</code> / <code>Shift+ArrowUp</code> / <code>Shift+ArrowDown</code></td><td>focus on crop-area, 未禁用且非只读</td><td>同上，一次走十个自然像素</td></tr><tr><td><code>ArrowLeft</code> / <code>ArrowRight</code> / <code>ArrowUp</code> / <code>ArrowDown</code></td><td>focus on crop-handle, 未禁用且非只读</td><td>这个把手负责的那条边或那个角挪一个自然像素，对面那条边钉住不动；锁了比例时另一条边跟着算</td></tr><tr><td><code>Shift+ArrowLeft</code> / <code>Shift+ArrowRight</code> / <code>Shift+ArrowUp</code> / <code>Shift+ArrowDown</code></td><td>focus on crop-handle, 未禁用且非只读</td><td>同上，一次走十个自然像素</td></tr><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>未禁用</td><td>裁切框与八个把手各占一个 Tab 停靠点，按文档序依次走过</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>crop-area</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>crop-area</code></td><td><code>aria-label</code></td><td>label.cropArea</td></tr><tr><td><code>crop-area</code></td><td><code>role</code></td><td>&#39;application&#39;</td></tr><tr><td><code>crop-handle</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>crop-handle</code></td><td><code>aria-label</code></td><td>label.handle(position)</td></tr><tr><td><code>crop-handle</code></td><td><code>aria-valuemax</code></td><td>String(HANDLE_AXIS[position] === &#39;width&#39; ? natural.wi…</td></tr><tr><td><code>crop-handle</code></td><td><code>aria-valuemin</code></td><td>String(HANDLE_AXIS[position] === &#39;width&#39; ? minWidth :…</td></tr><tr><td><code>crop-handle</code></td><td><code>aria-valuenow</code></td><td>String(HANDLE_AXIS[position] === &#39;width&#39; ? value.widt…</td></tr><tr><td><code>crop-handle</code></td><td><code>aria-valuetext</code></td><td>label.valueText({ ...value })</td></tr><tr><td><code>crop-handle</code></td><td><code>role</code></td><td>&#39;slider&#39;</td></tr><tr><td><code>grid</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><ul><li>读屏在浏览模式下把方向键收给虚拟光标，节点报成普通分组就等于键盘调整到不了组件。裁切框因此报成 <code>role=&quot;application&quot;</code>：焦点落进来读屏自动切焦点模式，方向键归组件。代价是这一小块（框内的参考线与把手）读不了虚拟光标的浏览命令；图片与它的 <code>alt</code> 在框外，不受影响。</li><li>八个把手各自报成 <code>role=&quot;slider&quot;</code>——它们是叶子节点，报成 slider 才有值语义。裁切框本身不能报 slider：规范里 slider 的子节点一律当装饰，那样八个把手会整批从无障碍树里消失。</li><li>把手的 <code>aria-valuenow</code> 报它推动的那条边长（上下两条边报高度，其余六个报宽度），四个数完整念一遍靠 <code>aria-valuetext</code>（<code>translations.valueText</code>，收一份裁切矩形、返回一句话）。裁切框自己没有值语义可挂：需要逐次播报平移结果的应用，自己挂一个 <code>aria-live</code> 区域监听 <code>onValueChange</code> 即可。</li><li>名字取自 <code>translations.cropArea</code> 与八条把手文案，缺省是英文，接入应用时请覆盖成本地语言。</li><li>键盘可以完成全部操作：裁切框上方向键平移，把手上方向键改尺寸，按住 Shift 走十倍。指针不是唯一路径。</li><li>整组禁用时裁切框与把手一起退出 Tab 序列——把手是原生按钮，不写 <code>tabindex</code> 照样可聚焦，所以禁用时给的是 <code>-1</code> 而不是不写；只读时仍可聚焦、仍念得出来，只是改不动。</li><li>图片的替代文本走根上的 <code>alt</code>（与 <code>src</code> 同一条通道，与 image / avatar 一致），由连接层写到 image 部件上；作者自己写在 image 节点上的 <code>alt</code> 会被覆盖。组件不替作者编描述：不给 <code>alt</code> 时落的是空串，读屏跳过这张图而不是改念图片地址。图有内容就把它写出来。</li><li>皮肤给每个把手铺了一层不可见的命中区，撑到最小可点尺寸；框拉得很小时相邻把手的命中区会挨上，需要更宽裕的话把 <code>--xh-image-cropper-handle-size</code> 调大。只放四个角的把手也是合法用法，剩下的边靠键盘调。</li></ul><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/image-cropper.css</code> 按部件选择：<code>[data-scope=&quot;image-cropper&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-shape</code></td><td>props.shape</td></tr><tr><td><code>crop-area</code></td><td><code>data-shape</code></td><td>props.shape</td></tr><tr><td><code>crop-handle</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>crop-handle</code></td><td><code>data-position</code></td><td>position</td></tr><tr><td><code>crop-handle</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>crop-handle</code></td><td><code>data-resizing</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>grid</code></td><td><code>data-shape</code></td><td>props.shape</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-image-cropper-bg</code> · <code>--xh-image-cropper-crop-border</code> · <code>--xh-image-cropper-grid-line</code> · <code>--xh-image-cropper-handle-bg</code> · <code>--xh-image-cropper-handle-bg-resizing</code> · <code>--xh-image-cropper-handle-border</code> · <code>--xh-image-cropper-handle-radius</code> · <code>--xh-image-cropper-handle-size</code> · <code>--xh-image-cropper-mask</code> · <code>--xh-image-cropper-radius</code> · <code>--xh-image-cropper-w</code></p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><ul><li>裁切矩形描述的是图片像素，坐标恒是物理方向：<code>x</code> 永远从图片左边缘算起，方向键的左右也永远对应图片的左右。整页 <code>dir=&quot;rtl&quot;</code> 时框不会翻到另一侧，组件因此不收 <code>dir</code>。</li><li>皮肤里裁切框与把手的落点跟着写物理属性，与连接层算出来的那份坐标同一口径，不依赖祖先链上的文字方向。</li></ul><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>配一个<a href="./slider">滑块</a>驱动 <code>zoom</code>，配两个<a href="./button">按钮</a>驱动 <code>rotation</code>，是最常见的一套工具条。</li><li>裁好之后把结果丢进<a href="./image">图片</a>做预览。</li><li>整套放进<a href="./dialog">对话框</a>里，确认时再出图。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>视口的尺寸要由图片撑出来（图片铺满视口、高度自适应），裁切框的百分比坐标才对得上。给视口写死一个与图片比例不同的高度，框会和图错位。</li><li>角色节点的结构有三条硬要求：crop-area 必须是 viewport 的后代（坐标以 viewport 的矩形为准），image 必须是原生 <code>&lt;img&gt;</code>（自然尺寸只有它的 load 事件报得出来），crop-handle 必须是原生 <code>&lt;button&gt;</code>。</li><li>Web Components 侧每个 crop-handle 都要自己写 <code>position=&quot;nw|n|ne|e|se|s|sw|w&quot;</code>——把手的身份只能从这个属性上取。写漏或写错的把手不接行为、控制台留一条诊断；Vue 侧同名 prop 是必填的，漏写会有告警。</li><li>给 <code>minWidth</code> / <code>minHeight</code> 定一个下限：不给的话用户能把框拉成一条线，出图是一张空图。</li><li>出图用导出的 <code>cropToCanvas(image, rect, options)</code>，在 <code>onValueChangeEnd</code> 或用户点确认时调一次即可；每帧都出图会把主线程占满。源图带透明像素又要存成 JPEG 时记得传 <code>background</code>，否则透明区会变成黑块。</li><li><code>cropToCanvas</code> 只按矩形裁，不烘焙旋转角度。要把旋转也固化进结果，请先把旋转后的图渲成一张新图再喂进来。</li><li>跨域图片要先设好 <code>crossorigin</code>，否则画布会被污染、<code>toDataURL</code> 直接抛错。</li><li>裁切框的描边与把手底色跟着主题的表面色走，而它们压着的是一张任意的图：图与主题表面色亮度相近时（深色主题配一张暗图、浅色主题配一张亮图）线会看不清。图源的亮度可预期时，用 <code>--xh-image-cropper-crop-border</code> 与 <code>--xh-image-cropper-handle-bg</code> 把这两处钉成与图对得起来的颜色。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>把 <code>zoom</code> 与 <code>rotation</code> 当成裁切参数来读：它们只是看图的辅助，产出永远以裁切矩形为准。</li><li>每次 <code>onValueChange</code> 都去服务端出图：拖动过程中这个回调一秒会发几十次，要发请求请用 <code>onValueChangeEnd</code>。</li><li>只提供指针操作、把八个把手做成两三个像素的小点：既碰不到也说不出，键盘与触屏用户都被挡在外面。</li></ul>',44))])}const P=l(p,[["render",g]]);export{q as __pageData,P as default};
